const q = $input.first().json.query || {};
if (q.token !== 'mercado-7d41c2a9e05b') return [{ json: { ok: false } }];
// desde hace 12 meses (hora de Colombia)
const d = new Date(Date.now() - 5 * 3600 * 1000);
d.setUTCDate(1); d.setUTCMonth(d.getUTCMonth() - 11);
return [{ json: { ok: true, desde: d.toISOString().slice(0, 10) } }];

// Lee una propiedad venga como página completa de Notion (properties) o simplificada de n8n (property_xxx)
const clave = (n) => 'property_' + String(n).toLowerCase().replace(/\s+/g, '_');
const txt = (a) => ((a || []).map(t => t.plain_text).join('') || '').trim();
const leer = (it, nombre, tipo) => {
  const pr = it.properties && it.properties[nombre];
  if (pr) {
    if (tipo === 'titulo') return txt(pr.title);
    if (tipo === 'texto') return txt(pr.rich_text);
    if (tipo === 'numero') return pr.number != null ? pr.number : null;
    if (tipo === 'fecha') return pr.date && pr.date.start ? pr.date.start.slice(0, 10) : null;
    if (tipo === 'select') return pr.select ? pr.select.name : (pr.status ? pr.status.name : null);
    if (tipo === 'relacion') return pr.relation && pr.relation[0] ? pr.relation[0].id : null;
  }
  let v = it[clave(nombre)];
  if (v === undefined && tipo === 'titulo') v = it.name;
  if (v === undefined || v === null || v === '') return null;
  if (tipo === 'fecha') { const s = typeof v === 'object' ? (v.start || '') : String(v); return s ? s.slice(0, 10) : null; }
  if (tipo === 'relacion') { const r = Array.isArray(v) ? v[0] : v; return r ? (typeof r === 'object' ? r.id : String(r)) : null; }
  if (tipo === 'numero') return typeof v === 'number' ? v : (Number(v) || null);
  return String(v);
};

const todos = $('Movimientos de Ema').all().map(i => i.json).filter(x => x && x.id);
const desde = $('Validar y preparar').first().json.desde || '0000-00-00';
// el nodo de Notion trae todo: el filtro se hace aquí (solo Salidas Ema de los últimos 12 meses)
// el día de la salida es «Fecha salida» si se pagó otro día (boletas compradas antes); si no, la fecha del gasto
const diaSalida = (x) => leer(x, 'Fecha salida', 'fecha') || leer(x, 'Fecha', 'fecha');
// es de una salida con Ema si «Salida» dice Con Ema (lo nuevo) o la categoría es Salidas Ema (lo de antes)
const esEma = (x) => leer(x, 'Salida', 'select') === 'Con Ema' || leer(x, 'Categoría', 'select') === 'Salidas Ema';
const movs = todos.filter(x => esEma(x) && (diaSalida(x) || '') >= desde);
const lugs = $input.all().map(i => i.json).filter(x => x && x.id);
const info = {};
for (const l of lugs) {
  info[l.id] = { id: l.id, nombre: leer(l, 'Nombre', 'titulo') || 'Lugar', puntuacion: leer(l, 'Puntuación', 'numero'),
    notas: leer(l, 'Notas', 'texto') || '', clase: leer(l, 'Clase', 'select') || 'Restaurante' };
}
const por = {}, diaTotal = {}, lugarDias = {};
for (const p of movs) {
  const f = diaSalida(p); if (!f) continue;
  const pagado = leer(p, 'Fecha', 'fecha');
  const monto = leer(p, 'Monto', 'numero') || 0;
  const concepto = leer(p, 'Concepto', 'titulo') || 'Gasto';
  const rel = leer(p, 'Restaurante', 'relacion');
  const nomLugar = rel && info[rel] ? info[rel].nombre : null;
  const mes = f.slice(0, 7);
  const m = por[mes] || (por[mes] = { mes, veces: 0, total: 0, dias: [], salidas: {} });
  m.total += monto;
  const s = m.salidas[f] || (m.salidas[f] = { fecha: f, total: 0, gastos: [] });
  s.total += monto;
  const g = { c: concepto, m: monto };
  if (nomLugar) g.l = nomLugar;
  if (pagado && pagado !== f) g.p = pagado;   // se pagó otro día
  s.gastos.push(g);
  diaTotal[f] = (diaTotal[f] || 0) + monto;
  if (rel) (lugarDias[rel] || (lugarDias[rel] = new Set())).add(f);
}
for (const m of Object.values(por)) {
  m.salidas = Object.values(m.salidas).sort((a, b) => a.fecha.localeCompare(b.fecha));
  m.dias = m.salidas.map(s => s.fecha);
  m.veces = m.salidas.length;
}
const meses = Object.values(por).sort((a, b) => a.mes.localeCompare(b.mes));
const lugares = Object.keys(lugarDias).map(id => {
  const dias = [...lugarDias[id]].sort();
  const costos = dias.map(d => diaTotal[d] || 0);
  const l = info[id] || { id, nombre: 'Lugar', puntuacion: null, notas: '', clase: 'Restaurante' };
  return { id, nombre: l.nombre, clase: l.clase, puntuacion: l.puntuacion, notas: l.notas, visitas: dias.length,
           promedio: Math.round(costos.reduce((a, b) => a + b, 0) / Math.max(1, costos.length)), ultima: dias[dias.length - 1] };
}).sort((a, b) => b.ultima.localeCompare(a.ultima));
for (const l of Object.values(info)) {
  if (l.clase === 'Plan Ema' && !lugares.find(x => x.id === l.id)) lugares.push({ id: l.id, nombre: l.nombre, clase: l.clase, puntuacion: l.puntuacion, notas: l.notas, visitas: 0, promedio: 0, ultima: null });
}
const nombres = Object.values(info).map(l => l.nombre).filter(Boolean).sort((a, b) => a.localeCompare(b, 'es'));
// ── citas en pareja: solo lo marcado como «Pareja» o que diga «pareja» (comer afuera solo suele ser en familia)
const NO_ES_SALIDA = /tarjeta|pago|cuota|salario|cr[eé]dito|transfer|abono|arriendo|deuda|pr[eé]stamo|seguro|regalo|impuesto|droguer/i;
const esPareja = (x) => {
  if (leer(x, 'Tipo', 'select') !== 'Gasto') return false;
  const c = leer(x, 'Concepto', 'titulo') || '';
  if (NO_ES_SALIDA.test(c)) return false;
  return leer(x, 'Salida', 'select') === 'Pareja' || /\bpareja\b/i.test(c);
};
const parejaPor = {};
for (const x of todos) {
  if (!esPareja(x)) continue;
  const f = leer(x, 'Fecha', 'fecha'); if (!f || f < desde) continue;
  const m = parejaPor[f.slice(0, 7)] || (parejaPor[f.slice(0, 7)] = { mes: f.slice(0, 7), veces: 0, total: 0, dias: {}, cosas: [] });
  const monto = leer(x, 'Monto', 'numero') || 0;
  m.total += monto; m.dias[f] = 1;
  m.cosas.push({ c: (leer(x, 'Concepto', 'titulo') || '').replace(/\s*\b(en )?pareja\b\s*/i, ' ').trim(), m: monto, f });
}
const pareja = Object.values(parejaPor).map(m => ({ mes: m.mes, veces: Object.keys(m.dias).length, total: m.total, cosas: m.cosas.sort((a, b) => a.f.localeCompare(b.f)) })).sort((a, b) => a.mes.localeCompare(b.mes));

// ── recurrentes: lo que se paga casi todos los meses y no varía mucho (fuera de comida, salidas y lo que llega solo del correo)
const hoyCo = new Date(Date.now() - 5 * 3600 * 1000);
const seisMeses = new Date(Date.UTC(hoyCo.getUTCFullYear(), hoyCo.getUTCMonth() - 5, 1)).toISOString().slice(0, 10);
const AUTOMATICO = /arriendo|jard[ií]n|cuota\s+(del\s+)?(carro|cr[eé]dito)|recibo|energ[ií]a|\bluz\b|\bagua\b|\bgas\b|internet|acueducto|emcali|celsia/i;
const SIN_RECURRENTE = ['Alimentación', 'Servicios', 'Salidas', 'Salidas Ema', 'Tarjetas', 'Ahorro'];
const grupos = {};
for (const x of todos) {
  const f = leer(x, 'Fecha', 'fecha'); if (!f || f < seisMeses) continue;
  const tipo = leer(x, 'Tipo', 'select'), cat = leer(x, 'Categoría', 'select') || 'Otros', con = (leer(x, 'Concepto', 'titulo') || '').trim();
  if (!con || (tipo === 'Gasto' && (SIN_RECURRENTE.includes(cat) || AUTOMATICO.test(con)))) continue;
  const k = tipo + '|' + con.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const g = grupos[k] || (grupos[k] = { tipo, concepto: con, cats: {}, meses: new Set(), montos: [], ultima: '' });
  g.meses.add(f.slice(0, 7)); g.montos.push(leer(x, 'Monto', 'numero') || 0); g.cats[cat] = (g.cats[cat] || 0) + 1;
  if (f >= g.ultima) { g.ultima = f; g.concepto = con; g.ultimoMonto = leer(x, 'Monto', 'numero') || 0; }
}
const recurrentes = Object.values(grupos).filter(g => g.meses.size >= 2).map(g => {
  const mn = Math.min(...g.montos), mx = Math.max(...g.montos), prom = g.montos.reduce((a, b) => a + b, 0) / g.montos.length;
  const varia = prom ? (mx - mn) / prom : 1;
  return { tipo: g.tipo, concepto: g.concepto, categoria: Object.entries(g.cats).sort((a, b) => b[1] - a[1])[0][0], monto: g.ultimoMonto, fijo: varia <= 0.03, varia, meses: g.meses.size, ultima: g.ultima };
}).filter(r => r.varia <= 1).sort((a, b) => b.meses - a.meses || b.monto - a.monto).map(({ varia, ...r }) => r);
return [{ json: { meses, lugares, nombres, pareja, recurrentes } }];
